      }}
    >
      {title}
    </h2>
    {children}
    <div
      style={{
        position: 'absolute',
        left: 140,
        right: 140,
        bottom: 44,
        fontSize: 22,
        color: muted,
        borderTop: `2px solid ${line}`,
        paddingTop: 14,
