{"file_path": "c:\Users\gianl\prova-slide\slides\database-prima\index.tsx", "content": "import type { DesignSystem, Page, SlideMeta } from '@open-slide/core';

export const design: DesignSystem = {
  palette: { bg: '#ffffff', text: '#1e293b', accent: '#2563eb' },
  fonts: {
    display: 'system-ui, -apple-system, "Segoe UI", sans-serif',
    body: 'system-ui, -apple-system, "Segoe UI", sans-serif',
  },
  typeScale: { hero: 160, body: 40 },
  radius: 16,
};

const muted = '#64748b';
const soft = '#eff6ff';
const line = '#e2e8f0';

const fill = {
  width: '100%',
  height: '100%',
  fontFamily: 'var(--osd-font-body)',
  background: 'var(--osd-bg)',
  color: 'var(--osd-text)',
} as const;

const Cover: Page = () => (
  <div
    style={{
      ...fill,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      padding: '0 160px',
    }}
  >
    <div style={{ fontSize: 28, letterSpacing: '0.2em', color: 'var(--osd-accent)', fontWeight: 700 }}>
      INFORMATICA · CLASSE PRIMA
    </div>
    <h1
      style={{
        fontFamily: 'var(--osd-font-display)',
        fontSize: 'var(--osd-size-hero)',
        fontWeight: 800,
        lineHeight: 1.1,
        margin: '32px 0',
      }}
    >
      I database
    </h1>
    <p style={{ fontSize: 48, color: muted, margin: 0, lineHeight: 1.4 }}>
      Dove i computer conservano le informazioni
    </p>
    <div style={{ width: 160, height: 8, background: 'var(--osd-accent)', borderRadius: 4, marginTop: 64 }} />
  </div>
);

const Cell = ({ children, head }: { children: string; head?: boolean }) => (
  <div
    style={{
      flex: 1,
      padding: '0 36px',
      fontSize: 36,
      fontWeight: head ? 700 : 400,
      color: head ? '#ffffff' : 'var(--osd-text)',
    }}
  >
    {children}
  </div>
);

const Row = ({ a, b, c, head }: { a: string; b: string; c: string; head?: boolean }) => (
  <div
    style={{
      display: 'flex',
      alignItems: 'center',
      height: 88,
      background: head ? 'var(--osd-accent)' : 'transparent',
      borderBottom: head ? 'none' : `2px solid ${line}`,
    }}
  >
    <Cell head={head}>{a}</Cell>
    <Cell head={head}>{b}</Cell>
    <Cell head={head}>{c}</Cell>
  </div>
);

const Structure: Page = () => (
  <div style={{ ...fill, padding: 120 }}>
    <h2 style={{ fontFamily: 'var(--osd-font-display)', fontSize: 80, fontWeight: 800, margin: 0, lineHeight: 1.2 }}>
      Un database è un insieme di tabelle
    </h2>
    <p style={{ fontSize: 'var(--osd-size-body)', color: muted, margin: '32px 0 56px', lineHeight: 1.5 }}>
      Esempio: la tabella degli studenti
    </p>
    <div
      style={{
        border: `2px solid ${line}`,
        borderRadius: 'var(--osd-radius)',
        overflow: 'hidden',
        width: 1500,
      }}
    >
      <Row head a="Nome" b="Cognome" c="Classe" />
      <Row a="Sara" b="Rossi" c="1A" />
      <Row a="Marco" b="Bianchi" c="1A" />
      <Row a="Giulia" b="Verdi" c="1B" />
    </div>
    <p style={{ fontSize: 36, color: muted, margin: '48px 0 0', lineHeight: 1.5 }}>
      Ogni <b style={{ color: 'var(--osd-accent)' }}>riga</b> è una persona, ogni{' '}
      <b style={{ color: 'var(--osd-accent)' }}>colonna</b> è un'informazione.
    </p>
  </div>
);

const Card = ({ emoji, title, text }: { emoji: string; title: string; text: string }) => (
  <div
    style={{
      flex: 1,
      background: soft,
      borderRadius: 'var(--osd-radius)',
      padding: 48,
      display: 'flex',
      flexDirection: 'column',
      gap: 20,
    }}
  >
    <div style={{ fontSize: 88, lineHeight: 1 }}>{emoji}</div>
    <div style={{ fontSize: 48, fontWeight: 700, lineHeight: 1.2 }}>{title}</div>
    <div style={{ fontSize: 32, color: muted, lineHeight: 1.5 }}>{text}</div>
  </div>
);

const Examples: Page = () => (
  <div style={{ ...fill, padding: 120 }}>
    <h2 style={{ fontFamily: 'var(--osd-font-display)', fontSize: 80, fontWeight: 800, margin: 0, lineHeight: 1.2 }}>
      Li usiamo ogni giorno
    </h2>
    <div style={{ display: 'flex', gap: 48, marginTop: 80 }}>
      <Card emoji="🏫" title="Scuola" text="Voti, classi e registro elettronico" />
      <Card emoji="🛒" title="Negozi online" text="Prodotti, prezzi e ordini" />
      <Card emoji="📱" title="Social" text="Profili, foto e messaggi" />
    </div>
    <p style={{ fontSize: 40, color: 'var(--osd-accent)', fontWeight: 600, margin: '72px 0 0' }}>
      Un database tiene i dati in ordine e li ritrova subito.
    </p>
  </div>
);

export const meta: SlideMeta = {
  title: 'I database',
  createdAt: '2026-11-02T18:58:04.603Z',
};
export default [Cover, Structure, Examples] satisfies Page[];
"}

